import clsx from 'clsx';
import { getBlockType } from '@wordpress/blocks';
import { Button } from '@wordpress/components';
import { VisuallyHidden } from '@wordpress/ui';
import { useInstanceId, useViewportMatch } from '@wordpress/compose';
import { useSelect, useDispatch } from '@wordpress/data';
import { forwardRef, useMemo } from '@wordpress/element';
import { __, isRTL, sprintf } from '@wordpress/i18n';
import { displayShortcut, shortcutAriaLabel } from '@wordpress/keycodes';
import {
	chevronLeft,
	chevronRight,
	chevronUp,
	chevronDown,
} from '@wordpress/icons';
import type { MouseEvent } from 'react';
import { getBlockMoverDescription } from './mover-description';
import { store as blockEditorStore } from '../../store';
import type {
	BlockMoverButtonProps,
	BlockMoverDirection,
	BlockMoverOrientation,
} from './types';

const getArrowIcon = (
	direction: BlockMoverDirection,
	orientation: BlockMoverOrientation
) => {
	if ( direction === 'up' ) {
		if ( orientation === 'horizontal' ) {
			return isRTL() ? chevronRight : chevronLeft;
		}
		return chevronUp;
	} else if ( direction === 'down' ) {
		if ( orientation === 'horizontal' ) {
			return isRTL() ? chevronLeft : chevronRight;
		}
		return chevronDown;
	}
	return null;
};

const getMovementDirectionLabel = (
	moveDirection: BlockMoverDirection,
	orientation: BlockMoverOrientation
) => {
	if ( moveDirection === 'up' ) {
		if ( orientation === 'horizontal' ) {
			return isRTL() ? __( 'Move right' ) : __( 'Move left' );
		}
		return __( 'Move up' );
	} else if ( moveDirection === 'down' ) {
		if ( orientation === 'horizontal' ) {
			return isRTL() ? __( 'Move left' ) : __( 'Move right' );
		}
		return __( 'Move down' );
	}
	return null;
};

const BlockMoverButton = forwardRef<
	HTMLButtonElement,
	BlockMoverButtonProps & { direction: BlockMoverDirection }
>(
	(
		{ clientIds, direction, orientation: moverOrientation, ...props },
		ref
	) => {
		const instanceId = useInstanceId( BlockMoverButton );
		const normalizedClientIds = useMemo(
			() => ( Array.isArray( clientIds ) ? clientIds : [ clientIds ] ),
			[ clientIds ]
		);
		const blocksCount = normalizedClientIds.length;
		const hasBlocks = !! normalizedClientIds[ 0 ];
		const isMobileViewport = useViewportMatch( 'small', '<' );

		const {
			blockType,
			isDisabled,
			rootClientId,
			isFirst,
			isLast,
			firstIndex,
			orientation = 'vertical',
		} = useSelect(
			( select ) => {
				const {
					getBlockIndex,
					getBlockRootClientId,
					getBlockOrder,
					getBlock,
					getBlockListSettings,
				} = select( blockEditorStore );
				const firstClientId = normalizedClientIds[ 0 ];
				const blockRootClientId = getBlockRootClientId( firstClientId );
				const firstBlockIndex = getBlockIndex( firstClientId );
				const lastBlockIndex = getBlockIndex(
					normalizedClientIds[ normalizedClientIds.length - 1 ]
				);
				const blockOrder = getBlockOrder( blockRootClientId );
				const block = getBlock( firstClientId );
				const isFirstBlock = firstBlockIndex === 0;
				const isLastBlock = lastBlockIndex === blockOrder.length - 1;
				const { orientation: blockListOrientation } =
					getBlockListSettings( blockRootClientId ) || {};

				return {
					blockType: block ? getBlockType( block.name ) : null,
					isDisabled:
						! firstClientId ||
						( direction === 'up' ? isFirstBlock : isLastBlock ),
					rootClientId: blockRootClientId,
					firstIndex: firstBlockIndex,
					isFirst: isFirstBlock,
					isLast: isLastBlock,
					orientation: moverOrientation || blockListOrientation,
				};
			},
			[ direction, moverOrientation, normalizedClientIds ]
		);

		const { moveBlocksDown, moveBlocksUp } =
			useDispatch( blockEditorStore );
		const moverFunction =
			direction === 'up' ? moveBlocksUp : moveBlocksDown;

		const onClick = ( event: MouseEvent< HTMLButtonElement > ) => {
			moverFunction( clientIds, rootClientId );
			if ( props.onClick ) {
				props.onClick( event );
			}
		};

		const descriptionId = `block-editor-block-mover-button__description-${ instanceId }`;
		const keyCharacter = direction === 'up' ? 't' : 'y';

		return (
			<>
				<Button
					__next40pxDefaultSize
					ref={ ref }
					className={ clsx(
						'block-editor-block-mover-button',
						`is-${ direction }-button`
					) }
					icon={ getArrowIcon( direction, orientation ) }
					// Both directions have a label.
					label={ getMovementDirectionLabel(
						direction,
						orientation
					)! }
					tooltipPosition={
						! isMobileViewport &&
						direction === 'down' &&
						orientation === 'vertical'
							? 'bottom'
							: 'top'
					}
					aria-describedby={ hasBlocks ? descriptionId : undefined }
					{ ...props }
					// The button ignores a `null` click handler.
					onClick={
						( isDisabled ? null : onClick ) as typeof onClick
					}
					disabled={ isDisabled }
					accessibleWhenDisabled
					shortcut={ displayShortcut.secondary( keyCharacter ) }
				/>
				{ hasBlocks && (
					<VisuallyHidden id={ descriptionId }>
						{ sprintf(
							// translators: 1: Description of the block movement. 2: Keyboard shortcut.
							__( '%1$s (%2$s)' ),
							getBlockMoverDescription(
								blocksCount,
								// A described block has a block type.
								( blockType && blockType.title ) as string,
								firstIndex,
								isFirst,
								isLast,
								direction === 'up' ? -1 : 1,
								orientation
								// The mover is shown for positions it can describe.
							) as string,
							// The secondary modifier has a label.
							shortcutAriaLabel.secondary(
								keyCharacter
							) as string
						) }
					</VisuallyHidden>
				) }
			</>
		);
	}
);

export const BlockMoverUpButton = forwardRef<
	HTMLButtonElement,
	BlockMoverButtonProps
>( ( props, ref ) => {
	return <BlockMoverButton direction="up" ref={ ref } { ...props } />;
} );

export const BlockMoverDownButton = forwardRef<
	HTMLButtonElement,
	BlockMoverButtonProps
>( ( props, ref ) => {
	return <BlockMoverButton direction="down" ref={ ref } { ...props } />;
} );
